M1:
run: dispatch -> {
  group_by: station
  aggregate: e is net_cleared_mwh
  order_by: e desc, station
  limit: 1
}

M2:
run: dispatch -> {
  where: region = 'SA1' and TOTALCLEARED > 0
  aggregate: n is unit_count
}

M3:
run: dispatch -> {
  group_by: region
  aggregate: e is net_cleared_mwh
  order_by: e desc, region
  limit: 1
}

M4:
run: interconnector_flows -> {
  where: interconnector = 'VIC1-NSW1' and MWFLOW > 0 and nsw_price.RRP - vic_price.RRP > 10
  aggregate: n is interval_count
}

M5:
run: region_totals -> {
  group_by: region
  aggregate: a is avg_net_interchange_mw
  order_by: a desc, region
  limit: 1
}

M6:
run: interconnector_flows -> {
  group_by: interconnector
  aggregate: a is avg_losses_mw
  order_by: a desc, interconnector
  limit: 1
}

M7:
source: peak_interval_load is dispatch extend {
  join_one: peak is (prices -> {
    where: region = 'SA1'
    group_by: interval_end
    aggregate: p is max_price
    order_by: p desc, interval_end
    limit: 1
  }) on interval_end = peak.interval_end
}
run: peak_interval_load -> {
  where: region = 'SA1' and peak.interval_end is not null
  group_by: duid
  aggregate: mw is max_cleared_mw
  order_by: mw desc, duid
  limit: 1
}

M8:
run: dispatch -> {
  where: region = 'NSW1'
  group_by: duid
  aggregate: m is net_cleared_mw_sum
} -> {
  group_by: duid, m
  order_by: m desc
  calculate: rk is row_number()
} -> {
  aggregate: share is round(m.sum() { where: rk <= 5 } / m.sum(), 3)
}

M9:
run: region_totals -> {
  group_by: interval_end
  aggregate: s is sum_net_interchange_mw
  having: abs(s) > 50
} -> {
  aggregate: n is count()
}

M10:
run: units -> {
  group_by: station
  aggregate: c is unit_count
  order_by: c desc, station
  limit: 1
}
